print(json.dumps(result, separators=(',', ':')))

import java.util.*;

class Solution {
    public int[] twoSum(int[] nums, long target) {
        Map<Long, Integer> seen = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            long complement = target - nums[i];
            if (seen.containsKey(complement)) {
                return new int[] { seen.get(complement), i };
            }
            seen.put((long)nums[i], i);
        }
        return new int[0];
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String line = sc.nextLine();
        line = line.substring(1, line.length()-1);
        String[] parts = line.split(",");
        int[] nums = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            nums[i] = Integer.parseInt(parts[i]);
        }

        long target = sc.nextLong();

        Solution sol = new Solution();
        int[] result = sol.twoSum(nums, target);

        System.out.print("[");
        for (int i = 0; i < result.length; i++) {
            System.out.print(result[i]);
            if (i < result.length - 1) System.out.print(",");
        }
        System.out.println("]");
    }
}

const readline = require('readline');
const rl = readline.createInterface({input: process.stdin});

class Solution {
    twoSum(nums, target) {
        const seen = new Map();
        for (let i = 0; i < nums.length; i++) {
            const complement = target - nums[i];
            if (seen.has(complement)) {
                return [seen.get(complement), i];
            }
            seen.set(nums[i], i);
        }
        return [];
    }
}

const lines = [];
rl.on('line', (line) => lines.push(line));
rl.on('close', () => {
    const nums = JSON.parse(lines[0]);
    const target = parseInt(lines[1]);
    const sol = new Solution();
    const result = sol.twoSum(nums, target);
    console.log(JSON.stringify(result));
});

#include <iostream>
#include <vector>
#include <unordered_map>
#include <sstream>
using namespace std;

class Solution {
public:
    vector<int> twoSum(vector<long long>& nums, long long target) {
        unordered_map<long long, int> seen;
        for (int i = 0; i < nums.size(); i++) {
            long long complement = target - nums[i];
            if (seen.find(complement) != seen.end()) {
                return {seen[complement], i};
            }
            seen[nums[i]] = i;
        }
        return {};
    }
};

int main() {
    string line;
    getline(cin, line);

    vector<long long> nums;
    stringstream ss(line.substr(1, line.length()-2));
    string num;
    while (getline(ss, num, ',')) {
        nums.push_back(stoll(num));
    }

    long long target;
    cin >> target;

    Solution sol;
    vector<int> result = sol.twoSum(nums, target);

    cout << "[" << result[0] << "," << result[1] << "]" << endl;
    return 0;
}
